mapper.select:
SELECT

, b.unid as unid,
b.email as email
FROM Order4Game a left join Account b on a.accountId = b.id
WHERE 1 = 1

    AND a.id = #{id}


    AND a.orderTxNo LIKE CONCAT('%',#{orderTxNo}, '%')


    AND a.gameId = #{gameId}


    AND a.accountId = #{accountId}


    AND a.gamePrizeId = #{gamePrizeId}


    AND a.gamePrizeName LIKE CONCAT('%',#{gamePrizeName}, '%') 


    AND a.orderStatus = #{orderStatus}


    AND a.isWinning = #{isWinning}

order by a.createTime desc
